// ── Proving lifetimes with GUIDs ──
public class TransientService { public Guid Id = Guid.NewGuid(); }
public class ScopedService    { public Guid Id = Guid.NewGuid(); }
public class SingletonService  { public Guid Id = Guid.NewGuid(); }

// In a controller:
public class TestController(TransientService t1, TransientService t2,
    ScopedService s1, ScopedService s2, SingletonService g) : ControllerBase {

    [HttpGet]
    public IActionResult Get() => Ok(new {
        Transient1 = t1.Id,    // different GUID
        Transient2 = t2.Id,    // different GUID
        Scoped1 = s1.Id,       // SAME GUID (same request)
        Scoped2 = s2.Id,       // SAME GUID (same request)
        Singleton = g.Id       // SAME GUID (always)
    });
}

