var builder = WebApplication.CreateBuilder(args);

// Define a named CORS policy
builder.Services.AddCors(options => {
    options.AddPolicy("Frontend", policy => {
        policy.WithOrigins(
                "https://myapp.com",
                "http://localhost:3000")  // dev frontend
            .AllowAnyMethod()       // GET, POST, PUT, DELETE
            .AllowAnyHeader()       // Authorization, Content-Type, etc.
            .AllowCredentials();    // cookies & auth headers
    });

    // Restrictive policy for third-party
    options.AddPolicy("ThirdParty", policy => {
        policy.WithOrigins("https://partner.com")
            .WithMethods("GET")     // read-only!
            .WithHeaders("X-Api-Key");
    });
});

var app = builder.Build();

// Apply CORS — MUST be before UseAuthorization!
app.UseCors("Frontend");
app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();

