// ── Custom Action Filter: Log Execution Time ──
public class ExecutionTimeFilter : IActionFilter {
    private readonly ILogger<ExecutionTimeFilter> _logger;
    private Stopwatch? _stopwatch;

    public ExecutionTimeFilter(ILogger<ExecutionTimeFilter> logger)
        => _logger = logger;

    public void OnActionExecuting(ActionExecutingContext context) {
        _stopwatch = Stopwatch.StartNew();
        _logger.LogInformation("Executing: {Action}",
            context.ActionDescriptor.DisplayName);
    }

    public void OnActionExecuted(ActionExecutedContext context) {
        _stopwatch?.Stop();
        _logger.LogInformation("Executed in {Ms}ms",
            _stopwatch?.ElapsedMilliseconds);
    }
}

// ── API Key Validation Filter (short-circuit) ──
public class ApiKeyFilter : IActionFilter {
    public void OnActionExecuting(ActionExecutingContext context) {
        if (!context.HttpContext.Request.Headers
            .TryGetValue("X-Api-Key", out var key) || key != "secret") {
            context.Result = new UnauthorizedResult(); // skip action!
        }
    }
    public void OnActionExecuted(ActionExecutedContext context) { }
}

// ── Register globally ──
builder.Services.AddControllers(options => {
    options.Filters.Add<ExecutionTimeFilter>();  // runs on every action
});

// ── Or per-controller ──
[ServiceFilter(typeof(ApiKeyFilter))]
public class SecureController : ControllerBase { }
